script:
(function () {
  'use strict';
  // Nominal annual rate r compounded n times a year <-> effective annual rate E (APY):
  //   E = (1 + r/n)^n - 1               r = n * ((1 + E)^(1/n) - 1)
  //   continuous: E = e^r - 1           r = ln(1 + E)
  //   daily on a 360-day basis (r/360 credited for each of 365 days):
  //     E = (1 + r/360)^365 - 1          r = 360 * ((1 + E)^(1/365) - 1)
  // Verified (Node): 6% monthly -> 6.1678%; 12% quarterly -> 12.5509%; 5% daily (365) -> 5.1267%;
  // 10% continuous -> 10.5171%; 6% daily on a 360-day basis -> 6.2716%; round trips (E -> r -> E)
  // return the input to 1e-12; 0% -> 0% at every frequency.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var ROWS = [
    ['cont', 'Continuously'], ['365', 'Daily'], ['360', 'Daily, 360-day basis'], ['52', 'Weekly'], ['26', 'Biweekly'],
    ['24', 'Semimonthly'], ['12', 'Monthly'], ['6', 'Every two months'], ['4', 'Quarterly'], ['2', 'Semiannually'], ['1', 'Annually']
  ];

  // --- calc start
  // freq: 'cont', '360' (r/360 for 365 days) or a number of periods a year.
  function toEffective(r, freq) {
    if (freq === 'cont') return Math.exp(r) - 1;
    if (freq === '360') return Math.pow(1 + r / 360, 365) - 1;
    var n = Number(freq);
    return Math.pow(1 + r / n, n) - 1;
  }

  function toNominal(e, freq) {
    if (freq === 'cont') return Math.log(1 + e);
    if (freq === '360') return 360 * (Math.pow(1 + e, 1 / 365) - 1);
    var n = Number(freq);
    return n * (Math.pow(1 + e, 1 / n) - 1);
  }

  function periodsPerYear(freq) {
    if (freq === 'cont') return Infinity;
    if (freq === '360') return 365;
    return Number(freq);
  }

  function periodicRate(r, freq) {
    if (freq === 'cont') return null;
    if (freq === '360') return r / 360;
    return r / Number(freq);
  }
  // --- calc end

  function el(id) { return document.getElementById(id); }
  function pct(x, dp) {
    return (x * 100).toLocaleString('en-US', { minimumFractionDigits: dp, maximumFractionDigits: dp }) + '%';
  }
  function periodsText(freq) {
    if (freq === 'cont') return 'Unlimited';
    if (freq === '360') return '365 (at r/360 a day)';
    return Number(freq).toLocaleString('en-US');
  }

  function clear() {
    ['erMain', 'erOther', 'erPeriodic', 'erInterest', 'erPeriods', 'erGap', 'erEnd'].forEach(function (id) {
      el(id).textContent = '–';
    });
    el('erTable').innerHTML = '';
  }

  function update() {
    var toEff = el('erDirection').value === 'toEffective';
    var sel = el('erFreq').value;
    el('erCustomWrap').hidden = sel !== 'custom';
    el('erRateWrap').querySelector('label').textContent = toEff ? 'Nominal annual rate (APR)' : 'Effective annual rate (APY)';
    el('erMainLabel').textContent = toEff ? 'Effective annual rate (APY)' : 'Nominal annual rate (APR)';
    el('erOtherLabel').textContent = toEff ? 'Nominal annual rate (APR)' : 'Effective annual rate (APY)';
    el('erTableIntro').textContent = toEff
      ? 'The effective rate you get from the same nominal rate at each compounding frequency.'
      : 'The nominal rate needed at each compounding frequency to give the same effective rate.';

    var rate = parseFloat(el('erRate').value), custom = parseFloat(el('erCustom').value);
    var amountText = el('erAmount').value.trim(), amount = amountText === '' ? 0 : parseFloat(amountText);
    var msg = '';
    if (isNaN(rate) || rate < 0 || rate > 100) msg = 'Enter a rate from 0% to 100%.';
    else if (sel === 'custom' && (isNaN(custom) || custom < 1 || custom > 100000 || Math.round(custom) !== custom)) msg = 'Enter a whole number of compounding periods from 1 to 100,000.';
    else if (isNaN(amount) || amount < 0 || amount > 1e12) msg = 'Enter an example balance from $0 to $1 trillion.';
    var error = el('erError');
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) { clear(); return; }

    var freq = sel === 'custom' ? String(custom) : sel;
    var r = rate / 100, nominal, effective;
    if (toEff) { nominal = r; effective = toEffective(r, freq); }
    else { effective = r; nominal = toNominal(r, freq); }
    var periodic = periodicRate(nominal, freq);

    el('erMain').textContent = pct(toEff ? effective : nominal, 4);
    el('erOther').textContent = pct(toEff ? nominal : effective, 4);
    el('erPeriodic').textContent = periodic === null ? 'Not applicable' : pct(periodic, 6);
    el('erInterest').textContent = money.format(amount * effective);
    el('erPeriods').textContent = periodsText(freq);
    el('erGap').textContent = ((effective - nominal) * 100).toLocaleString('en-US', { minimumFractionDigits: 4, maximumFractionDigits: 4 }) + ' percentage points';
    el('erEnd').textContent = money.format(amount * (1 + effective));
    var note = el('erNote');
    note.hidden = true;
    if (freq === '360') {
      note.textContent = 'On a 360-day basis the daily rate is the annual rate divided by 360 but is charged or paid for all 365 days, so the effective rate is a little higher than with ordinary daily compounding.';
      note.hidden = false;
    }

    el('erTable').innerHTML = ROWS.map(function (row) {
      var n = toEff ? r : toNominal(r, row[0]);
      var e = toEff ? toEffective(r, row[0]) : r;
      return '<tr><td>' + row[1] + '</td><td>' + periodsText(row[0]) + '</td><td>' + pct(n, 4) + '</td><td>' + pct(e, 4) + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('erForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
